SET NAMES utf8mb4;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('manager','assistant') NOT NULL,status ENUM('active','disabled') NOT NULL DEFAULT 'active',two_factor_secret VARCHAR(64) NULL,two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(100) UNIQUE NOT NULL,label VARCHAR(150) NOT NULL) ENGINE=InnoDB;
CREATE TABLE user_permissions(user_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,permission_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE grade_levels(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE groups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,grade_level_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,color CHAR(7) DEFAULT '#315eea',monthly_fee DECIMAL(12,2) NOT NULL DEFAULT 0,FOREIGN KEY(grade_level_id) REFERENCES grade_levels(id)) ENGINE=InnoDB;
CREATE TABLE students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,group_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,joined_at DATE NOT NULL,monthly_fee_override DECIMAL(12,2) NULL,fee_exempt TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','inactive','archived') DEFAULT 'active',archived_at DATETIME NULL,archived_by BIGINT UNSIGNED NULL,archive_reason VARCHAR(255) NULL,FOREIGN KEY(group_id) REFERENCES groups(id),INDEX(group_id,joined_at)) ENGINE=InnoDB;
CREATE TABLE student_phones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,phone_encrypted TEXT NOT NULL,phone_hash CHAR(64) NOT NULL,is_primary TINYINT(1) DEFAULT 0,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,INDEX(phone_hash)) ENGINE=InnoDB;
CREATE TABLE monthly_fees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,fee_month DATE NOT NULL,base_amount DECIMAL(12,2) NOT NULL,assessed_amount DECIMAL(12,2) NOT NULL,previous_arrears DECIMAL(12,2) NOT NULL DEFAULT 0,paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('unpaid','partial','paid','exempt') NOT NULL,UNIQUE(student_id,fee_month),FOREIGN KEY(student_id) REFERENCES students(id),INDEX(fee_month,status)) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,monthly_fee_id BIGINT UNSIGNED NOT NULL,reference_no VARCHAR(40) UNIQUE NOT NULL,amount DECIMAL(12,2) NOT NULL,method VARCHAR(40),paid_at DATETIME NOT NULL,created_by BIGINT UNSIGNED NOT NULL,reversed_at DATETIME NULL,reversal_reason VARCHAR(255) NULL,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(monthly_fee_id) REFERENCES monthly_fees(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status ENUM('present','absent','excused') NOT NULL,created_by BIGINT UNSIGNED NOT NULL,UNIQUE(student_id,attendance_date),FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE exams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,group_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160),exam_date DATE,max_score DECIMAL(8,2),FOREIGN KEY(group_id) REFERENCES groups(id)) ENGINE=InnoDB;
CREATE TABLE exam_scores(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,score DECIMAL(8,2) NOT NULL,UNIQUE(exam_id,student_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE homework_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,assigned_date DATE NOT NULL,status ENUM('complete','incomplete','excused') NOT NULL,notes VARCHAR(255),FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE recitation_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,recitation_date DATE NOT NULL,errors_count INT UNSIGNED NOT NULL DEFAULT 0,notes VARCHAR(255),FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,type VARCHAR(60),title VARCHAR(180),body TEXT,is_read TINYINT(1) DEFAULT 0,created_at DATETIME NOT NULL,INDEX(user_id,is_read)) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,ip VARCHAR(45),metadata JSON NULL,created_at DATETIME NOT NULL,INDEX(user_id,created_at)) ENGINE=InnoDB;
INSERT INTO permissions(code,label) VALUES ('students.view','مشاهدة الطلاب'),('students.manage','إدارة الطلاب'),('attendance.manage','إدارة الحضور'),('exams.manage','إدارة الامتحانات'),('homework.manage','إدارة الواجب'),('recitation.manage','إدارة التسميع'),('finance.view','مشاهدة الماليات'),('finance.manage','إدارة الماليات'),('reports.export','تصدير التقارير'),('assistants.manage','إدارة المساعدين');
